44	        let Some(diagnostics) = diagnostics else {
45	            return Ok(DocumentDiagnosticReportResult::Report(
46	                DocumentDiagnosticReport::Full(RelatedFullDocumentDiagnosticReport::default()),
47	            ));
48	        };
49	
50	        let result_id = diagnostics.result_id();
51	
52	        let report = match result_id {
53	            Some(new_id) if Some(&new_id) == params.previous_result_id.as_ref() => {
54	                DocumentDiagnosticReport::Unchanged(RelatedUnchangedDocumentDiagnosticReport {
55	                    related_documents: None,
56	                    unchanged_document_diagnostic_report: UnchangedDocumentDiagnosticReport {
57	                        result_id: new_id,
58	                    },
59	                })
60	            }
61	            new_id => {
62	                DocumentDiagnosticReport::Full(RelatedFullDocumentDiagnosticReport {
63	                    related_documents: None,
64	                    full_document_diagnostic_report: FullDocumentDiagnosticReport {
65	                        result_id: new_id,
66	                        // SAFETY: Pull diagnostic requests are only called for text documents, not for
67	                        // notebook documents.
68	                        items: diagnostics
