70	                                db,
71	                                snapshot.resolved_client_capabilities(),
72	                                snapshot.global_settings(),
73	                            )
74	                            .expect_text_document(),
75	                    },
76	                })
77	            }
78	        };
79	
80	        Ok(DocumentDiagnosticReportResult::Report(report))
81	    }
