24	    fn document_url(params: &types::CodeAction) -> Cow<'_, types::Url> {
25	        let uri: lsp_types::Url = serde_json::from_value(params.data.clone().unwrap_or_default())
26	            .expect("code actions should have a URI in their data fields");
27	        Cow::Owned(uri)
28	    }
29	    fn run_with_snapshot(
30	        snapshot: DocumentSnapshot,
31	        _client: &Client,
32	        mut action: types::CodeAction,
33	    ) -> Result<types::CodeAction> {
34	        let query = snapshot.query();
35	
36	        let code_actions = SupportedCodeAction::from_kind(
37	            action
38	                .kind
39	                .clone()
40	                .ok_or(anyhow::anyhow!("No kind was given for code action"))
41	                .with_failure_code(ErrorCode::InvalidParams)?,
42	        )
43	        .collect::<Vec<_>>();
44	
45	        // Ensure that the code action maps to _exactly one_ supported code action
46	        let [action_kind] = code_actions.as_slice() else {
47	            return Err(anyhow::anyhow!(
48	                "Code action resolver did not expect code action kind {:?}",
49	                action.kind.as_ref().unwrap()
50	            ))
51	            .with_failure_code(ErrorCode::InvalidParams);
52	        };
53	
54	        match action_kind {
55	            SupportedCodeAction::SourceFixAll | SupportedCodeAction::SourceOrganizeImports
56	                if snapshot.is_notebook_cell() =>
57	            {
58	                // This should never occur because we ignore generating these code actions for a
59	                // notebook cell in the `textDocument/codeAction` request handler.
60	                return Err(anyhow::anyhow!(
61	                    "Code action resolver cannot resolve {:?} for a notebook cell",
62	                    action_kind.to_kind().as_str()
63	                ))
64	                .with_failure_code(ErrorCode::InvalidParams);
65	            }
66	            _ => {}
67	        }
68	
69	        action.edit = match action_kind {
70	            SupportedCodeAction::SourceFixAll | SupportedCodeAction::NotebookSourceFixAll => Some(
71	                resolve_edit_for_fix_all(
72	                    query,
73	                    snapshot.resolved_client_capabilities(),
74	                    snapshot.encoding(),
75	                )
76	                .with_failure_code(ErrorCode::InternalError)?,
77	            ),
78	            SupportedCodeAction::SourceOrganizeImports
79	            | SupportedCodeAction::NotebookSourceOrganizeImports => Some(
80	                resolve_edit_for_organize_imports(
81	                    query,
82	                    snapshot.resolved_client_capabilities(),
83	                    snapshot.encoding(),
84	                )
85	                .with_failure_code(ErrorCode::InternalError)?,
86	            ),
87	            SupportedCodeAction::QuickFix => {
88	                // The client may ask us to resolve a code action, as it has no way of knowing
89	                // whether e.g. `command` field will be filled out by the resolution callback.
90	                return Ok(action);
91	            }
92	        };
93	
94	        Ok(action)
95	    }
