impl SyncRequestHandler for CodeActionResolveHandler {
    fn run(
        _session: &mut Session,
        _client: &Client,
        action: types::CodeAction,
    ) -> Result<types::CodeAction> {
        // ty computes complete code actions -- including their edits -- eagerly
        // while handling `textDocument/codeAction`, so there is nothing to resolve
        // lazily here.
        //
        // A code action's `data` field, when present, carries the URL of the
        // document it applies to. If a client sends us an action without that
        // field, or with a `data` value that can't be parsed as a document URL,
        // we still return the action unchanged rather than failing the request.
        if let Some(data) = &action.data
            && serde_json::from_value::<Url>(data.clone()).is_err()
        {
            return Ok(action);
        }

        Ok(action)
    }
}
