use crate::server::Result;
use crate::server::api::RequestHandler;
use crate::server::api::traits::SyncRequestHandler;
use crate::session::Session;
use crate::session::client::Client;

pub(crate) struct CodeActionResolveHandler;

impl RequestHandler for CodeActionResolveHandler {
    type RequestType = CodeActionResolveRequest;
}

impl SyncRequestHandler for CodeActionResolveHandler {
    fn run(
        _session: &mut Session,
        _client: &Client,
        action: types::CodeAction,
    ) -> Result<types::CodeAction> {
        // ty computes complete code actions -- including their edits -- eagerly
        // while handling `textDocument/codeAction`, so there is nothing to resolve
        // lazily here. We return the action unchanged.
        //
        // This also means we gracefully handle actions that carry no `data` field,
        // or whose `data` field can't be parsed as the document URL that a resolve
        // step would otherwise need: we never fail such a request.
        Ok(action)
    }
}
